@@ -1,16 +1,28 @@
-const BARE_SECONDS = /^\d+$/;
-const COMPONENTS = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
+const SECONDS_PER_MINUTE = 60;
+const SECONDS_PER_HOUR = 60 * SECONDS_PER_MINUTE;
+
+const BARE_SECONDS_PATTERN = /^\d+$/;
+const UNIT_COMPONENTS_PATTERN = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
+
+function invalidDuration(text: string): Error {
+  return new Error(`Invalid duration: "${text}"`);
+}

 export function parseDuration(text: string): number {
-  if (BARE_SECONDS.test(text)) {
+  if (BARE_SECONDS_PATTERN.test(text)) {
     return Number(text);
   }

-  const match = COMPONENTS.exec(text);
+  // Every component is optional, so the pattern also matches "" — reject it explicitly.
+  const match = UNIT_COMPONENTS_PATTERN.exec(text);
   if (text === "" || match === null) {
-    throw new Error(`Invalid duration: "${text}"`);
+    throw invalidDuration(text);
   }

   const [, hours = "0", minutes = "0", seconds = "0"] = match;
-  return Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds);
+  return (
+    Number(hours) * SECONDS_PER_HOUR +
+    Number(minutes) * SECONDS_PER_MINUTE +
+    Number(seconds)
+  );
 }
